pr_comments:
We used to try to avoid ifdef spaghetti.
```
nt ossl_config_int(const OPENSSL_INIT_SETTINGS *settings)
{
#if defined(OPENSSL_SYS_UEFI)
    openssl_configured = 1;
    return 1;
#else
    int ret = 1;
    const char *filename = settings ? settings->filename : NULL;
    const char * appname = settings ? settings->appname : NULL;
    unsigned long flags = settings ? settings->flags : DEFAULT_CONF_MFLAGS;

    if (openssl_configured)
        return 1;

#ifdef OPENSSL_INIT_DEBUG
    fprintf(stderr, "OPENSSL_INIT: ossl_config_int(%s, %s, %lu)\n",
            filename, appname, flags);
#endif

    ret = CONF_modules_load_file(filename, appname, flags);
    openssl_configured = 1;
    return ret;
#endif
}
```

issue_context.body:
```ossl_config_int()``` alway return 0 on the first call in UEFI system.
```
crypto/conf/conf_sap.c L44
int ossl_config_int(const OPENSSL_INIT_SETTINGS *settings)
{
    int ret = 0;
......
#ifndef OPENSSL_SYS_UEFI
    ret = CONF_modules_load_file(filename, appname, flags);
#endif
    openssl_configured = 1;
    return ret;
}
```
Then the first call of ```evp_generic_fetch()``` will fail due to ```ossl_method_store_fetch()``` fail:
```
int ossl_method_store_fetch(OSSL_METHOD_STORE *store,
                            int nid, const char *prop_query,
                            const OSSL_PROVIDER **prov_rw, void **method)
{
......
    if (!OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG, NULL))
        return 0; // First call always return 0 here
.....
}
```
```ret``` only used to check return value of ```CONF_modules_load_file()```, should set it to 1 if in UEFI system.
